// ==================================================
// Tool Request Validator
//
// Validates untrusted tool requests while preserving
// the validation envelope expected by the workflow.
//
// Supported tools:
// - get_signins
// - get_endpoint_activity
// - get_ip_reputation
//
// plan_context contains orchestration metadata.
// It is validated and propagated, but it is NOT part
// of the connector parameters.
//
// Output:
// {
//   valid: boolean,
//   errors: [],
//   request: object | null
// }
// ==================================================

const input = $json;

const errors = [];


// --------------------------------------------------
// 1. Basic request validation
// --------------------------------------------------

if (
  !input ||
  typeof input !== "object" ||
  Array.isArray(input)
) {

  errors.push(
    "request must be an object"
  );
}


// --------------------------------------------------
// 2. Required top-level fields
// --------------------------------------------------

if (
  input?.request_version !== "1.0"
) {

  errors.push(
    "request_version must be '1.0'"
  );
}


if (
  typeof input?.alert_id !== "string" ||
  input.alert_id.trim() === ""
) {

  errors.push(
    "alert_id must be a non-empty string"
  );
}


if (
  typeof input?.step_id !== "string" ||
  input.step_id.trim() === ""
) {

  errors.push(
    "step_id must be a non-empty string"
  );
}


if (
  typeof input?.tool !== "string" ||
  input.tool.trim() === ""
) {

  errors.push(
    "tool must be a non-empty string"
  );
}


if (
  !input?.parameters ||
  typeof input.parameters !== "object" ||
  Array.isArray(input.parameters)
) {

  errors.push(
    "parameters must be an object"
  );
}


if (
  input?.context !== undefined &&
  (
    !input.context ||
    typeof input.context !== "object" ||
    Array.isArray(input.context)
  )
) {

  errors.push(
    "context must be an object when provided"
  );
}


// --------------------------------------------------
// 3. Validate optional plan_context
//
// This metadata is produced by the Investigation
// Orchestrator and is not passed as connector input.
// --------------------------------------------------

if (
  input?.plan_context !== undefined
) {

  if (
    !input.plan_context ||
    typeof input.plan_context !== "object" ||
    Array.isArray(input.plan_context)
  ) {

    errors.push(
      "plan_context must be an object when provided"
    );

  } else {

    const planContext =
      input.plan_context;


    if (
      planContext.plan_version !== undefined &&
      (
        typeof planContext.plan_version !== "string" ||
        planContext.plan_version.trim() === ""
      )
    ) {

      errors.push(
        "plan_context.plan_version must be a non-empty string when provided"
      );
    }


    if (
      planContext.iteration_number !== undefined &&
      planContext.iteration_number !== null &&
      (
        !Number.isInteger(
          planContext.iteration_number
        ) ||
        planContext.iteration_number < 0
      )
    ) {

      errors.push(
        "plan_context.iteration_number must be an integer >= 0 or null"
      );
    }


    if (
      planContext.objective !== undefined &&
      typeof planContext.objective !== "string"
    ) {

      errors.push(
        "plan_context.objective must be a string when provided"
      );
    }


    if (
      planContext.requested_steps !== undefined &&
      (
        !Number.isInteger(
          planContext.requested_steps
        ) ||
        planContext.requested_steps < 1
      )
    ) {

      errors.push(
        "plan_context.requested_steps must be an integer >= 1 when provided"
      );
    }


    // Only known orchestration metadata is accepted.

    const allowedPlanContextFields = [
      "plan_version",
      "iteration_number",
      "objective",
      "requested_steps"
    ];


    for (
      const field
      of Object.keys(planContext)
    ) {

      if (
        !allowedPlanContextFields.includes(
          field
        )
      ) {

        errors.push(
          `plan_context field '${field}' is not allowed`
        );
      }
    }
  }
}


// --------------------------------------------------
// 4. Tool policies
// --------------------------------------------------

const toolPolicies = {

  get_signins: {

    requiredParameters: [
      "user"
    ],

    allowedParameters: [
      "user",
      "time_range",
      "limit"
    ]
  },


  get_endpoint_activity: {

    requiredParameters: [
      "host"
    ],

    allowedParameters: [
      "host",
      "time_range",
      "limit"
    ]
  },


  get_ip_reputation: {

    requiredParameters: [
      "ip"
    ],

    allowedParameters: [
      "ip"
    ]
  }

};


// --------------------------------------------------
// 5. Tool allowlist
// --------------------------------------------------

const selectedPolicy =
  typeof input?.tool === "string"
    ? toolPolicies[input.tool]
    : undefined;


if (
  typeof input?.tool === "string" &&
  input.tool.trim() !== "" &&
  !selectedPolicy
) {

  errors.push(
    `tool '${input.tool}' is not supported`
  );
}


// --------------------------------------------------
// 6. Parameter validation
// --------------------------------------------------

if (
  selectedPolicy &&
  input?.parameters &&
  typeof input.parameters === "object" &&
  !Array.isArray(input.parameters)
) {

  // ----------------------------------------------
  // Required parameters
  // ----------------------------------------------

  for (
    const parameter
    of selectedPolicy.requiredParameters
  ) {

    if (
      !Object.prototype.hasOwnProperty.call(
        input.parameters,
        parameter
      )
    ) {

      errors.push(
        `parameter '${parameter}' is required for tool '${input.tool}'`
      );
    }
  }


  // ----------------------------------------------
  // Parameter allowlist
  // ----------------------------------------------

  for (
    const parameter
    of Object.keys(
      input.parameters
    )
  ) {

    if (
      !selectedPolicy.allowedParameters.includes(
        parameter
      )
    ) {

      errors.push(
        `parameter '${parameter}' is not allowed for tool '${input.tool}'`
      );
    }
  }
}


// --------------------------------------------------
// 7. get_signins validation
// --------------------------------------------------

if (
  input?.tool === "get_signins" &&
  input?.parameters &&
  typeof input.parameters === "object"
) {

  const {
    user,
    time_range,
    limit
  } =
    input.parameters;


  if (
    typeof user !== "string" ||
    user.trim() === ""
  ) {

    errors.push(
      "get_signins.user must be a non-empty string"
    );

  } else if (
    user.length > 320
  ) {

    errors.push(
      "get_signins.user exceeds maximum length"
    );
  }


  if (
    time_range !== undefined &&
    (
      !time_range ||
      typeof time_range !== "object" ||
      Array.isArray(time_range)
    )
  ) {

    errors.push(
      "get_signins.time_range must be an object"
    );
  }


  if (
    limit !== undefined &&
    (
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 500
    )
  ) {

    errors.push(
      "get_signins.limit must be an integer between 1 and 500"
    );
  }
}


// --------------------------------------------------
// 8. get_endpoint_activity validation
// --------------------------------------------------

if (
  input?.tool === "get_endpoint_activity" &&
  input?.parameters &&
  typeof input.parameters === "object"
) {

  const {
    host,
    time_range,
    limit
  } =
    input.parameters;


  if (
    typeof host !== "string" ||
    host.trim() === ""
  ) {

    errors.push(
      "get_endpoint_activity.host must be a non-empty string"
    );

  } else if (
    host.length > 255
  ) {

    errors.push(
      "get_endpoint_activity.host exceeds maximum length"
    );
  }


  if (
    time_range !== undefined &&
    (
      !time_range ||
      typeof time_range !== "object" ||
      Array.isArray(time_range)
    )
  ) {

    errors.push(
      "get_endpoint_activity.time_range must be an object"
    );
  }


  if (
    limit !== undefined &&
    (
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 500
    )
  ) {

    errors.push(
      "get_endpoint_activity.limit must be an integer between 1 and 500"
    );
  }
}


// --------------------------------------------------
// 9. get_ip_reputation validation
// --------------------------------------------------

if (
  input?.tool === "get_ip_reputation" &&
  input?.parameters &&
  typeof input.parameters === "object"
) {

  const ip =
    input.parameters.ip;


  if (
    typeof ip !== "string" ||
    ip.trim() === ""
  ) {

    errors.push(
      "get_ip_reputation.ip must be a non-empty string"
    );

  } else {

    if (
      ip.length > 45
    ) {

      errors.push(
        "get_ip_reputation.ip exceeds maximum length"
      );
    }


    const ipv4Pattern =
      /^(25[0-5]|2[0-4]\d|1?\d?\d)(\.(25[0-5]|2[0-4]\d|1?\d?\d)){3}$/;


    const ipv6Pattern =
      /^[0-9a-fA-F:]+$/;


    const looksLikeIPv4 =
      ipv4Pattern.test(ip);


    const looksLikeIPv6 =
      ip.includes(":") &&
      ipv6Pattern.test(ip);


    if (
      !looksLikeIPv4 &&
      !looksLikeIPv6
    ) {

      errors.push(
        "get_ip_reputation.ip is not a valid IPv4 or IPv6 address"
      );
    }
  }
}


// --------------------------------------------------
// 10. Build canonical request
// --------------------------------------------------

let canonicalRequest =
  null;


if (
  errors.length === 0
) {

  canonicalRequest = {

    request_version:
      input.request_version,

    alert_id:
      input.alert_id,

    step_id:
      input.step_id,

    tool:
      input.tool,

    parameters:
      input.parameters,

    context:
      input.context || {},

    plan_context:
      (
        input.plan_context &&
        typeof input.plan_context === "object" &&
        !Array.isArray(input.plan_context)
      )
        ? {
            plan_version:
              input.plan_context.plan_version ?? "1.0",

            iteration_number:
              input.plan_context.iteration_number ?? null,

            objective:
              input.plan_context.objective ?? "",

            requested_steps:
              input.plan_context.requested_steps ?? null
          }
        : null
  };
}


// --------------------------------------------------
// 11. Return validation envelope
// --------------------------------------------------

return {
  json: {

    valid:
      errors.length === 0,

    errors,

    request:
      canonicalRequest
  }
};

const validationResult = $json;

return [
  {
    json: {
      status: "rejected",

      reason:
        "tool_request_validation_failed",

      errors:
        validationResult.errors || [],

      request:
        validationResult.request || null
    }
  }
];

const validationResult = $json;

if (validationResult.valid !== true) {
  throw new Error(
    "Validated Tool Request received an invalid request"
  );
}

return [
  {
    json: validationResult.request
  }
];

// ==================================================
// get_signins Mock Connector
//
// Simulates a security data source.
//
// No real API call is performed.
// ==================================================

const request = $json;

const parameters =
  request.parameters || {};

const user =
  parameters.user;

const timeRange =
  parameters.time_range || null;

const limit =
  parameters.limit || 100;


// --------------------------------------------------
// Simulated provider events
// --------------------------------------------------

const simulatedEvents = [

  {
    timestamp:
      "2026-08-23T17:20:00Z",

    user:
      "john.doe@example.com",

    source_ip:
      "185.220.101.20",

    status:
      "success",

    authentication_method:
      "MFA",

    application:
      "Microsoft 365",

    device:
      "WIN11-LAPTOP-01",

    location: {
      country:
        "Spain",

      city:
        "Madrid"
    }
  },


  {
    timestamp:
      "2026-08-23T17:42:00Z",

    user:
      "john.doe@example.com",

    source_ip:
      "91.198.174.20",

    status:
      "success",

    authentication_method:
      "MFA",

    application:
      "Microsoft 365",

    device:
      null,

    location: {
      country:
        "Netherlands",

      city:
        "Amsterdam"
    }
  }

];


// --------------------------------------------------
// Filter by requested user
// --------------------------------------------------

let events =
  simulatedEvents.filter(
    event =>
      event.user === user
  );


// --------------------------------------------------
// Optional time range
// --------------------------------------------------

if (timeRange) {

  const start =
    Date.parse(timeRange.start);

  const end =
    Date.parse(timeRange.end);

  events =
    events.filter(event => {

      const timestamp =
        Date.parse(event.timestamp);

      return (
        timestamp >= start &&
        timestamp <= end
      );
    });
}


// --------------------------------------------------
// Apply limit
// --------------------------------------------------

events =
  events.slice(0, limit);


// --------------------------------------------------
// Canonical tool result
// --------------------------------------------------

return [
  {
    json: {
      tool:
        "get_signins",

      tool_version:
        "1.0",

      status:
        "success",

      query: {
        user,
        time_range:
          timeRange
      },

      result_count:
        events.length,

      events,

      error:
        null
    }
  }
];

// ==================================================
// get_signins Output Validator
//
// Deterministically validates the canonical output
// produced by the get_signins connector.
// ==================================================

const result = $json;

const errors = [];


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function requireString(field, value) {
  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function validDate(value) {
  return (
    typeof value === "string" &&
    !Number.isNaN(Date.parse(value))
  );
}


// --------------------------------------------------
// Top-level validation
// --------------------------------------------------

if (result.tool !== "get_signins") {
  errors.push(
    "tool must be 'get_signins'"
  );
}


if (result.tool_version !== "1.0") {
  errors.push(
    "tool_version must be '1.0'"
  );
}


const validStatuses = [
  "success",
  "partial",
  "error"
];

if (
  !validStatuses.includes(
    result.status
  )
) {
  errors.push(
    "status contains an invalid value"
  );
}


// --------------------------------------------------
// Query validation
// --------------------------------------------------

if (
  typeof result.query !== "object" ||
  result.query === null ||
  Array.isArray(result.query)
) {
  errors.push(
    "query must be an object"
  );
} else {

  requireString(
    "query.user",
    result.query.user
  );


  if (
    result.query.time_range !== null &&
    result.query.time_range !== undefined
  ) {

    if (
      typeof result.query.time_range !== "object" ||
      Array.isArray(result.query.time_range)
    ) {
      errors.push(
        "query.time_range must be an object or null"
      );
    } else {

      if (
        !validDate(
          result.query.time_range.start
        )
      ) {
        errors.push(
          "query.time_range.start must be a valid timestamp"
        );
      }

      if (
        !validDate(
          result.query.time_range.end
        )
      ) {
        errors.push(
          "query.time_range.end must be a valid timestamp"
        );
      }
    }
  }
}


// --------------------------------------------------
// result_count
// --------------------------------------------------

if (
  !Number.isInteger(
    result.result_count
  ) ||
  result.result_count < 0
) {
  errors.push(
    "result_count must be a non-negative integer"
  );
}


// --------------------------------------------------
// events
// --------------------------------------------------

if (!Array.isArray(result.events)) {

  errors.push(
    "events must be an array"
  );

} else {

  if (
    Number.isInteger(result.result_count) &&
    result.result_count !==
      result.events.length
  ) {
    errors.push(
      "result_count does not match events.length"
    );
  }


  const validEventStatuses = [
    "success",
    "failure",
    "unknown"
  ];


  result.events.forEach(
    (event, index) => {

      const prefix =
        `events[${index}]`;


      if (
        typeof event !== "object" ||
        event === null ||
        Array.isArray(event)
      ) {
        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      if (
        !validDate(
          event.timestamp
        )
      ) {
        errors.push(
          `${prefix}.timestamp must be a valid timestamp`
        );
      }


      requireString(
        `${prefix}.user`,
        event.user
      );


      if (
        event.source_ip !== null &&
        typeof event.source_ip !== "string"
      ) {
        errors.push(
          `${prefix}.source_ip must be a string or null`
        );
      }


      if (
        !validEventStatuses.includes(
          event.status
        )
      ) {
        errors.push(
          `${prefix}.status contains an invalid value`
        );
      }


      if (
        event.authentication_method !== null &&
        event.authentication_method !== undefined &&
        typeof event.authentication_method !== "string"
      ) {
        errors.push(
          `${prefix}.authentication_method must be a string or null`
        );
      }


      if (
        event.application !== null &&
        event.application !== undefined &&
        typeof event.application !== "string"
      ) {
        errors.push(
          `${prefix}.application must be a string or null`
        );
      }


      if (
        event.device !== null &&
        event.device !== undefined &&
        typeof event.device !== "string"
      ) {
        errors.push(
          `${prefix}.device must be a string or null`
        );
      }


      if (
        event.location !== null &&
        event.location !== undefined
      ) {

        if (
          typeof event.location !== "object" ||
          Array.isArray(event.location)
        ) {
          errors.push(
            `${prefix}.location must be an object or null`
          );
        } else {

          if (
            event.location.country !== null &&
            event.location.country !== undefined &&
            typeof event.location.country !== "string"
          ) {
            errors.push(
              `${prefix}.location.country must be a string or null`
            );
          }


          if (
            event.location.city !== null &&
            event.location.city !== undefined &&
            typeof event.location.city !== "string"
          ) {
            errors.push(
              `${prefix}.location.city must be a string or null`
            );
          }
        }
      }
    }
  );
}


// --------------------------------------------------
// error
// --------------------------------------------------

if (
  result.error !== null &&
  result.error !== undefined
) {

  if (
    typeof result.error !== "object" ||
    Array.isArray(result.error)
  ) {
    errors.push(
      "error must be an object or null"
    );
  } else {

    requireString(
      "error.code",
      result.error.code
    );

    requireString(
      "error.message",
      result.error.message
    );
  }
}


// --------------------------------------------------
// Reject invalid connector output
// --------------------------------------------------

if (errors.length > 0) {
  throw new Error(
    `get_signins output validation failed: ${errors.join("; ")}`
  );
}


// --------------------------------------------------
// Canonical result
// --------------------------------------------------

return [
  {
    json: result
  }
];

// ==================================================
// Canonical Tool Result
//
// Produces the generic evidence contract consumed by
// the Investigation Evidence Aggregator.
//
// All tool-specific output validators converge here.
//
// Orchestration metadata is recovered only from the
// already-validated Tool Request Validator envelope.
// It is never trusted from connector output.
// ==================================================

const result = $json;


// --------------------------------------------------
// 1. Basic validation
// --------------------------------------------------

if (
  !result ||
  typeof result !== "object" ||
  Array.isArray(result)
) {
  throw new Error(
    "Canonical Tool Result requires a valid tool result object"
  );
}


if (
  typeof result.tool !== "string" ||
  result.tool.trim() === ""
) {
  throw new Error(
    "Canonical Tool Result requires tool"
  );
}


if (
  typeof result.version !== "string" ||
  result.version.trim() === ""
) {
  throw new Error(
    "Canonical Tool Result requires version"
  );
}


if (
  typeof result.status !== "string" ||
  result.status.trim() === ""
) {
  throw new Error(
    "Canonical Tool Result requires status"
  );
}


if (
  !result.query ||
  typeof result.query !== "object" ||
  Array.isArray(result.query)
) {
  throw new Error(
    "Canonical Tool Result requires query as an object"
  );
}


if (
  !Number.isInteger(result.result_count) ||
  result.result_count < 0
) {
  throw new Error(
    "Canonical Tool Result requires result_count as an integer >= 0"
  );
}


if (
  !Array.isArray(result.evidence)
) {
  throw new Error(
    `Canonical Tool Result: tool '${result.tool}' does not contain an evidence array`
  );
}


// --------------------------------------------------
// 2. Consistency check
// --------------------------------------------------

if (
  result.result_count !==
  result.evidence.length
) {
  throw new Error(
    `Canonical Tool Result: result_count does not match evidence.length for tool '${result.tool}'`
  );
}


// --------------------------------------------------
// 3. Retrieve validated original request
//
// IMPORTANT:
// We recover orchestration metadata from the
// validator output, not from the connector result.
// --------------------------------------------------

const validationEnvelope =
  $("Tool Request Validator")
    .first()
    .json;


if (
  !validationEnvelope ||
  typeof validationEnvelope !== "object" ||
  Array.isArray(validationEnvelope)
) {
  throw new Error(
    "Canonical Tool Result could not retrieve Tool Request Validator output"
  );
}


if (
  validationEnvelope.valid !== true
) {
  throw new Error(
    "Canonical Tool Result cannot process a request that did not pass Tool Request Validator"
  );
}


const validatedRequest =
  validationEnvelope.request;


if (
  !validatedRequest ||
  typeof validatedRequest !== "object" ||
  Array.isArray(validatedRequest)
) {
  throw new Error(
    "Canonical Tool Result could not retrieve the validated tool request"
  );
}


// --------------------------------------------------
// 4. Cross-check request/result identity
// --------------------------------------------------

if (
  typeof validatedRequest.alert_id !== "string" ||
  validatedRequest.alert_id.trim() === ""
) {
  throw new Error(
    "Canonical Tool Result validated request does not contain alert_id"
  );
}


if (
  typeof validatedRequest.step_id !== "string" ||
  validatedRequest.step_id.trim() === ""
) {
  throw new Error(
    "Canonical Tool Result validated request does not contain step_id"
  );
}


if (
  validatedRequest.tool !==
  result.tool
) {
  throw new Error(
    `Canonical Tool Result tool mismatch: validated request expected '${validatedRequest.tool}' but connector returned '${result.tool}'`
  );
}


if (
  result.alert_id !== undefined &&
  result.alert_id !== null &&
  result.alert_id !== validatedRequest.alert_id
) {
  throw new Error(
    "Canonical Tool Result alert_id does not match the validated request"
  );
}


if (
  result.step_id !== undefined &&
  result.step_id !== null &&
  result.step_id !== validatedRequest.step_id
) {
  throw new Error(
    "Canonical Tool Result step_id does not match the validated request"
  );
}


// --------------------------------------------------
// 5. Recover validated orchestration metadata
// --------------------------------------------------

let planContext =
  null;


if (
  validatedRequest.plan_context &&
  typeof validatedRequest.plan_context === "object" &&
  !Array.isArray(validatedRequest.plan_context)
) {

  planContext = {

    plan_version:
      validatedRequest.plan_context.plan_version ?? "1.0",

    iteration_number:
      validatedRequest.plan_context.iteration_number ?? null,

    objective:
      validatedRequest.plan_context.objective ?? "",

    requested_steps:
      validatedRequest.plan_context.requested_steps ?? null
  };
}


// --------------------------------------------------
// 6. Return generic canonical evidence result
// --------------------------------------------------

return {
  json: {

    evidence_version:
      "1.0",

    source:
      "tool",

    alert_id:
      validatedRequest.alert_id,

    step_id:
      validatedRequest.step_id,

    tool:
      result.tool,

    version:
      result.version,

    status:
      result.status,

    query:
      result.query,

    result_count:
      result.result_count,

    evidence:
      result.evidence,

    error:
