const request = $json;

const parameters =
  request.parameters || {};

const host =
  parameters.host;

const timeRange =
  parameters.time_range || null;

const limit =
  parameters.limit || 100;


// --------------------------------------------------
// 1. Simulated endpoint telemetry
// --------------------------------------------------

const simulatedEvents = [

