      timeRange.start
    );

  const end =
    Date.parse(
      timeRange.end
    );


  events =
    events.filter(
      event => {

        const timestamp =
          Date.parse(
            event.timestamp
          );

        return (
          timestamp >= start &&
          timestamp <= end
        );
      }
    );
}


