// ==================================================
// get_ip_reputation Output Validator
//
// Validates and canonicalizes output from the
// get_ip_reputation connector.
//
// Connector output is treated as untrusted input.
// ==================================================

const result = $json;

const errors = [];


// --------------------------------------------------
// Helpers
// --------------------------------------------------

function requireString(
  field,
  value
) {

  if (
    typeof value !== "string" ||
    value.trim() === ""
  ) {
    errors.push(
      `${field} must be a non-empty string`
    );
  }
}


function requireNumberRange(
  field,
  value,
  min,
  max
) {

  if (
    typeof value !== "number" ||
    Number.isNaN(value) ||
    value < min ||
    value > max
  ) {
    errors.push(
      `${field} must be a number between ${min} and ${max}`
    );
  }
}


// --------------------------------------------------
// 1. Metadata
// --------------------------------------------------

if (
  result.tool !==
    "get_ip_reputation"
) {
  errors.push(
    "tool must be 'get_ip_reputation'"
  );
}


if (
  result.version !==
    "1.0"
) {
  errors.push(
    "version must be '1.0'"
  );
}


const validStatuses = [
  "success",
  "partial",
  "error"
];


if (
  !validStatuses.includes(
    result.status
  )
) {
  errors.push(
    "status contains an invalid value"
  );
}


// --------------------------------------------------
// 2. Preserve orchestration metadata
// --------------------------------------------------

requireString(
  "alert_id",
  result.alert_id
);


requireString(
  "step_id",
  result.step_id
);


// --------------------------------------------------
// 3. Query
// --------------------------------------------------

if (
  !result.query ||
  typeof result.query !== "object" ||
  Array.isArray(result.query)
) {

  errors.push(
    "query must be an object"
  );

} else {

  requireString(
    "query.ip",
    result.query.ip
  );
}


// --------------------------------------------------
// 4. result_count
// --------------------------------------------------

if (
  !Number.isInteger(
    result.result_count
  ) ||
  result.result_count < 0
) {
  errors.push(
    "result_count must be an integer greater than or equal to 0"
  );
}


// --------------------------------------------------
// 5. results
// --------------------------------------------------

if (
  !Array.isArray(
    result.results
  )
) {

  errors.push(
    "results must be an array"
  );

} else {

  if (
    Number.isInteger(
      result.result_count
    ) &&
    result.result_count !==
      result.results.length
  ) {
    errors.push(
      "result_count does not match results.length"
    );
  }


  result.results.forEach(
    (item, index) => {

      const prefix =
        `results[${index}]`;


      if (
        !item ||
        typeof item !== "object" ||
        Array.isArray(item)
      ) {

        errors.push(
          `${prefix} must be an object`
        );

        return;
      }


      // ------------------------------------------
      // IP
      // ------------------------------------------

      requireString(
        `${prefix}.ip`,
        item.ip
      );


      // The returned entity must correspond to
      // the requested entity.

      if (
        result?.query?.ip &&
        item.ip !==
          result.query.ip
      ) {

        errors.push(
          `${prefix}.ip does not match query.ip`
        );
      }


      // ------------------------------------------
      // Classification
      // ------------------------------------------

      const validClassifications = [
        "benign",
        "suspicious",
        "malicious",
        "unknown"
      ];


      if (
        !validClassifications.includes(
          item.classification
        )
      ) {
        errors.push(
          `${prefix}.classification contains an invalid value`
        );
      }


      // ------------------------------------------
      // Reputation score
      // ------------------------------------------

      requireNumberRange(
        `${prefix}.reputation_score`,
        item.reputation_score,
        0,
        100
      );


      // ------------------------------------------
      // Confidence
      // ------------------------------------------

      requireNumberRange(
        `${prefix}.confidence`,
        item.confidence,
        0,
        1
      );


      // ------------------------------------------
      // Provider
      // ------------------------------------------

      requireString(
        `${prefix}.provider`,
        item.provider
      );


      // ------------------------------------------
      // Categories
      // ------------------------------------------

      if (
        !Array.isArray(
          item.categories
        )
      ) {

        errors.push(
          `${prefix}.categories must be an array`
        );

      } else {

        item.categories.forEach(
          (category, categoryIndex) => {

            if (
              typeof category !== "string" ||
              category.trim() === ""
            ) {
              errors.push(
                `${prefix}.categories[${categoryIndex}] must be a non-empty string`
              );
            }
          }
        );
      }


      // ------------------------------------------
      // last_seen
      // ------------------------------------------

      if (
        item.last_seen !== null &&
        typeof item.last_seen !== "string"
      ) {
        errors.push(
          `${prefix}.last_seen must be a string or null`
        );
      }


      if (
        typeof item.last_seen === "string" &&
        Number.isNaN(
          Date.parse(
            item.last_seen
          )
        )
      ) {
        errors.push(
          `${prefix}.last_seen must contain a valid ISO 8601 timestamp`
        );
      }


      // ------------------------------------------
      // details
      // ------------------------------------------

      if (
        !item.details ||
        typeof item.details !== "object" ||
        Array.isArray(item.details)
      ) {
        errors.push(
          `${prefix}.details must be an object`
        );
      }
    }
  );
}


// --------------------------------------------------
// 6. Error
// --------------------------------------------------

if (
  result.error !== null
) {

  if (
    !result.error ||
    typeof result.error !== "object" ||
    Array.isArray(result.error)
  ) {

    errors.push(
      "error must be null or an object"
    );

  } else {

    requireString(
      "error.code",
      result.error.code
    );

    requireString(
      "error.message",
      result.error.message
    );
  }
}


// --------------------------------------------------
// 7. Semantic status checks
// --------------------------------------------------

if (
  result.status === "success" &&
  result.error !== null
) {
  errors.push(
    "successful get_ip_reputation result must have error = null"
  );
}


if (
  result.status === "error" &&
  result.error === null
) {
  errors.push(
    "failed get_ip_reputation result must contain error information"
  );
}


// --------------------------------------------------
// 8. Reject invalid connector output
// --------------------------------------------------

if (
  errors.length > 0
) {
  throw new Error(
    `get_ip_reputation output validation failed: ${errors.join("; ")}`
  );
}


// --------------------------------------------------
// 9. Canonical tool result
// --------------------------------------------------

return {
  json: {

    request_version:
      result.request_version || "1.0",

    alert_id:
      result.alert_id,

    step_id:
      result.step_id,

    tool:
      "get_ip_reputation",

    version:
      result.version,

    status:
      result.status,

    query:
      result.query,

    result_count:
      result.result_count,

    evidence:
      result.results,

    error:
      result.error
  }
};
